import{_t as e,it as t,n,rt as r}from"./chunks/framework.DaD4z1Q-.js";var i=JSON.parse(`{"title":"Exclude packages and symbols from prefixing","description":"Leave packages, namespaces, functions, constants and files unprefixed, use the WordPress, WooCommerce and WP-CLI presets, and see why with explain.","frontmatter":{"title":"Exclude packages and symbols from prefixing","description":"Leave packages, namespaces, functions, constants and files unprefixed, use the WordPress, WooCommerce and WP-CLI presets, and see why with explain."},"headers":[],"relativePath":"guide/exclusions.md","filePath":"guide/exclusions.md"}`),a={name:`guide/exclusions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="leaving-things-alone" tabindex="-1">Leaving things alone <a class="header-anchor" href="#leaving-things-alone" aria-label="Permalink to “Leaving things alone”">​</a></h1><p>Most of the time you want everything renamed. Sometimes you do not, and Strauss-RS has a few ways to say so. Each one is listed in full on the <a href="/strauss-rs/reference/configuration.html">configuration page</a>. This page explains when to use which.</p><p>To find out why a symbol was or was not renamed, run <code>explain</code>. It names the setting that decided it:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/strauss-rs.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dd</span></span></code></pre></div><h2 id="a-whole-package" tabindex="-1">A whole package <a class="header-anchor" href="#a-whole-package" aria-label="Permalink to “A whole package”">​</a></h2><p>Use <code>exclude_from_prefix.packages</code> to copy a package without renaming anything in it:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;exclude_from_prefix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">		&quot;packages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;symfony/polyfill-mbstring&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>To leave a package out of the copy entirely, use <code>exclude_from_copy.packages</code>. This also works for namespaces and file patterns.</p><h2 id="a-namespace-or-some-files" tabindex="-1">A namespace or some files <a class="header-anchor" href="#a-namespace-or-some-files" aria-label="Permalink to “A namespace or some files”">​</a></h2><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;exclude_from_prefix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">		&quot;namespaces&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Psr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Log&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">		&quot;file_patterns&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/Legacy/~&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Namespaces are matched exactly, along with everything inside them. File patterns are regular expressions matched against paths relative to <code>vendor/</code>.</p><h2 id="one-function" tabindex="-1">One function <a class="header-anchor" href="#one-function" aria-label="Permalink to “One function”">​</a></h2><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;exclude_from_prefix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">		&quot;functions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The function is not renamed where it is declared, where it is called, or inside strings such as <code>function_exists(&#39;dd&#39;)</code>. Names are matched without regard to case, and a leading backslash is ignored. A function in a namespace is written in full, for example <code>Acme\\Lib\\helper</code>.</p><h2 id="one-constant" tabindex="-1">One constant <a class="header-anchor" href="#one-constant" aria-label="Permalink to “One constant”">​</a></h2><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;exclude_constants&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">		&quot;constants&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;WP_PLUGIN_DIR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ABSPATH&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>exclude_constants</code> also takes <code>packages</code>, <code>namespaces</code> and <code>file_patterns</code>, and they apply to constants only.</p><h2 id="a-function-name-inside-a-string" tabindex="-1">A function name inside a string <a class="header-anchor" href="#a-function-name-inside-a-string" aria-label="Permalink to “A function name inside a string”">​</a></h2><p>Some functions are renamed where they are called, but their name also appears in a string for another reason, for example as an array key. <code>exclude_from_string_rename</code> leaves the string alone:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;exclude_from_string_rename&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">		&quot;functions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;when&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to “Presets”">​</a></h2><p>Some libraries declare symbols that the platform they run on already has, usually in a shim guarded by <code>function_exists()</code> or <code>class_exists()</code>. If that shim were renamed, the platform would never see it and the shim would stop doing its job. <code>exclude_presets</code> lists sets of symbols that are never renamed:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;exclude_presets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wordpress&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;php-constants&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Preset</th><th>Covers</th><th>On by default</th></tr></thead><tbody><tr><td><code>wordpress</code></td><td>Wordpress core&#39;s global classes (<code>WP_Error</code>, <code>wpdb</code>), functions (<code>add_action</code>) and constants (<code>ABSPATH</code>)</td><td>Yes</td></tr><tr><td><code>woocommerce</code></td><td>WooCommerce&#39;s global classes (<code>WC_Order</code>), functions (<code>wc_get_order</code>) and constants (<code>WC_ABSPATH</code>)</td><td>No</td></tr><tr><td><code>wp-cli</code></td><td>WP-CLI&#39;s global classes (<code>WP_CLI</code>, <code>WP_CLI_Command</code>, <code>Plugin_Command</code>) and constants (<code>WP_CLI</code>)</td><td>No</td></tr><tr><td><code>php-constants</code></td><td>The constants PHP and its extensions define (<code>MB_CASE_TITLE</code>, <code>JSON_THROW_ON_ERROR</code>, <code>E_ALL</code>)</td><td>No</td></tr></tbody></table><ul><li>Setting <code>exclude_presets</code> replaces the default, so list <code>wordpress</code> too if you want it alongside the others. <code>&quot;exclude_presets&quot;: []</code> renames those symbols like any others.</li><li>Namespaced symbols are not included, so a bundled copy of something like <code>WpOrg\\Requests</code> or <code>Automattic\\WooCommerce\\Client</code> is still prefixed.</li><li>PHP&#39;s own classes and functions are always left alone, whatever you set here. This includes functions that only some PHP setups provide, such as <code>getallheaders()</code>.</li></ul><h3 id="php-constants" tabindex="-1">php-constants <a class="header-anchor" href="#php-constants" aria-label="Permalink to “php-constants”">​</a></h3><p>PHP&#39;s constants are not left alone by default, because a package may mean to define a constant of its own. This matters for polyfills. <code>symfony/polyfill-mbstring</code> declares <code>MB_CASE_TITLE</code> for a PHP without the mbstring extension. Without this preset, the constant is renamed to something like <code>ACME_MB_CASE_TITLE</code>, which PHP never defines, and code that uses it fails with an undefined constant error. Turn on <code>php-constants</code> if you bundle any polyfills.</p><p>The list covers the extensions of the PHP it was built with, plus a short list of extras. A constant from an extension it did not know about is still renamed, and <code>exclude_constants.constants</code> can cover it.</p><h3 id="woocommerce-and-wp-cli" tabindex="-1">woocommerce and wp-cli <a class="header-anchor" href="#woocommerce-and-wp-cli" aria-label="Permalink to “woocommerce and wp-cli”">​</a></h3><p>Turn on <code>woocommerce</code> or <code>wp-cli</code> if your plugin extends them, so a library&#39;s own shim for their classes is not renamed.</p><h2 id="files-in-your-own-project" tabindex="-1">Files in your own project <a class="header-anchor" href="#files-in-your-own-project" aria-label="Permalink to “Files in your own project”">​</a></h2><p><code>exclude_files_from_update</code> stops Strauss-RS changing files in your own code when <code>update_call_sites</code> is on. It takes <code>packages</code>, <code>namespaces</code> and <code>file_patterns</code>.</p>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};